/*
======================================================================
  ANALISTA JÚNIOR COM IA | Módulo 4: SQL
  Arquivo de prática: FData | IF.data, Banco Central do Brasil
  Origem: planilha FData_Junho_2026.xlsx, aba Base_FData
  Dados de referência: Junho/2026 (data-base 06/2026)
  Valores monetários em R$ mil (R$ 1 bilhão = 1.000.000)

  COMO USAR:
  1. Execute a PARTE 1 (Setup) para criar as tabelas e a view
  2. Execute a PARTE 2 (Dados) para inserir os registros
  3. Execute a PARTE 3 (Verificação) para confirmar o carregamento
  4. Pratique os Exemplos da PARTE 4
  5. Resolva os Exercícios da PARTE 5 (os mesmos das abas
     Exerc_Básico e Exerc_Intermediário, agora em SQL)
  6. Compare com o Gabarito da PARTE 6 (com o resultado esperado,
     conferido contra a planilha)
  7. Use a Análise Final da PARTE 7 para o projeto do módulo

  COMPATIBILIDADE: PostgreSQL (recomendado) / Supabase
  Para SQLite: substitua SERIAL por INTEGER, remova :: e use CAST();
               PERCENTILE_CONT não existe no SQLite
  Para MySQL:  substitua SERIAL por AUTO_INCREMENT

  DIFERENÇAS EM RELAÇÃO À PLANILHA:
  - "NI" (não informado na fonte) vira NULL. As 51 instituições com NI
    entram nas contagens, mas ficam fora de SUM, AVG e PERCENTILE,
    exatamente como as funções MÉDIA, SOMA e MED do Excel ignoram texto.
  - O schema contém apenas as colunas do dataset original do IF.data.
    As colunas criadas na planilha (U Tipo de Controle, V Índice
    Crédito/Ativo, W ROE do semestre, X Porte e Y Classe ROE) ficam
    de fora: quando um exercício precisa de um desses indicadores, ele
    é calculado dentro da própria consulta.
  - Data "06/2026" vira DATE '2026-06-01' (mês de referência, mesma
    convenção do arquivo M4_IFdata_Pratica).
  - A coluna "codigo" é a raiz do CNPJ sem zeros à esquerda, como na
    planilha (o Banco do Brasil aparece como '0').
    Para o formato de 8 dígitos: LPAD(codigo, 8, '0').

  NOTA: Este arquivo usa dados reais do sistema financeiro brasileiro.
  A base IF.data está disponível em: https://www3.bcb.gov.br/ifdata
*/


-- ====================================================================
-- PARTE 1 | SETUP: CRIAÇÃO DAS TABELAS
-- ====================================================================

-- Limpar objetos se já existirem (dependentes primeiro)
DROP VIEW  IF EXISTS vw_base_fdata;
DROP TABLE IF EXISTS estrutura;
DROP TABLE IF EXISTS financeiros;
DROP TABLE IF EXISTS instituicoes;
DROP TABLE IF EXISTS tipos_instituicao;
DROP TABLE IF EXISTS tipos_controle;
DROP TABLE IF EXISTS tipos_consolidado;

-- Tabelas de códigos (aba Dicionário da planilha)
CREATE TABLE tipos_consolidado (
    tcb         VARCHAR(3) PRIMARY KEY,   -- Tipo de Consolidado Bancário
    descricao   VARCHAR(120) NOT NULL
);

CREATE TABLE tipos_controle (
    tc          SMALLINT PRIMARY KEY,     -- 1=Público  2=Priv.Nac.  3=Priv.Estr.
    descricao   VARCHAR(40) NOT NULL
);

CREATE TABLE tipos_instituicao (
    ti          SMALLINT PRIMARY KEY,     -- Tipo de Instituição
    descricao   VARCHAR(80) NOT NULL
);

-- Tabelas principais (mesma divisão do arquivo M4_IFdata_Pratica)
CREATE TABLE instituicoes (
    id                          SERIAL PRIMARY KEY,
    nome                        VARCHAR(200) NOT NULL,
    codigo                      VARCHAR(8) NOT NULL UNIQUE,  -- raiz do CNPJ
    conglomerado_prudencial     VARCHAR(60),   -- nome; NULL = não integra
    cod_conglomerado_financeiro VARCHAR(8),    -- formato C0000000
    cod_conglomerado_prudencial VARCHAR(8),    -- formato C0000000
    tcb                         VARCHAR(3)  REFERENCES tipos_consolidado(tcb),
    tc                          SMALLINT    REFERENCES tipos_controle(tc),
    ti                          SMALLINT    REFERENCES tipos_instituicao(ti),
    cidade                      VARCHAR(80),
    uf                          CHAR(2)
);

CREATE TABLE financeiros (
    id                  SERIAL PRIMARY KEY,
    inst_id             INTEGER NOT NULL REFERENCES instituicoes(id),
    data_ref            DATE NOT NULL,
    ativo_total         BIGINT,   -- NULL = NI na fonte
    carteira_credito    BIGINT,
    tvm                 BIGINT,   -- Títulos e Valores Mobiliários
    passivo_exigivel    BIGINT,
    captacoes           BIGINT,
    patrimonio_liquido  BIGINT,   -- pode ser negativo
    lucro_liquido       BIGINT,   -- acumulado no semestre; negativo = prejuízo
    UNIQUE (inst_id, data_ref)
);

CREATE TABLE estrutura (
    id              SERIAL PRIMARY KEY,
    inst_id         INTEGER NOT NULL REFERENCES instituicoes(id),
    data_ref        DATE NOT NULL,
    num_agencias    INTEGER DEFAULT 0,
    num_postos      INTEGER DEFAULT 0,
    UNIQUE (inst_id, data_ref)
);


