-- --------------------------------------------------------------------
-- VIEW vw_base_fdata: reúne as três tabelas na mesma ordem de colunas
-- do dataset original (aba Base_FData, colunas A a T), sem nenhuma
-- coluna calculada.
-- --------------------------------------------------------------------

CREATE VIEW vw_base_fdata AS
SELECT
    i.id,
    i.nome,
    i.codigo,
    i.conglomerado_prudencial,
    i.cod_conglomerado_financeiro,
    i.cod_conglomerado_prudencial,
    i.tcb,
    i.tc,
    i.ti,
    i.cidade,
    i.uf,
    f.data_ref,
    f.ativo_total,
    f.carteira_credito,
    f.tvm,
    f.passivo_exigivel,
    f.captacoes,
    f.patrimonio_liquido,
    f.lucro_liquido,
    e.num_agencias,
    e.num_postos
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
JOIN estrutura e   ON e.inst_id = i.id AND e.data_ref = f.data_ref;


-- ====================================================================
-- PARTE 3 | VERIFICAÇÃO
-- ====================================================================

SELECT 'instituicoes' AS tabela, COUNT(*) AS registros FROM instituicoes
UNION ALL
SELECT 'financeiros',  COUNT(*) FROM financeiros
UNION ALL
SELECT 'estrutura',    COUNT(*) FROM estrutura
UNION ALL
SELECT 'vw_base_fdata', COUNT(*) FROM vw_base_fdata;
-- Esperado: 1622 registros em cada uma

SELECT * FROM instituicoes ORDER BY id LIMIT 5;
SELECT * FROM financeiros  ORDER BY id LIMIT 5;
SELECT * FROM estrutura    ORDER BY id LIMIT 5;
SELECT * FROM vw_base_fdata ORDER BY id LIMIT 5;

-- Instituições com NI na fonte (valores monetários NULL)
SELECT COUNT(*) AS qtd_ni
FROM financeiros
WHERE ativo_total IS NULL;
-- Esperado: 51

-- Conferência com a aba Tabela_TCB (qtd. e Soma do Ativo Total)
SELECT
    i.tcb,
    COUNT(*)            AS qtd,
    SUM(f.ativo_total)  AS ativo_soma
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
GROUP BY i.tcb
ORDER BY ativo_soma DESC;
-- Esperado: b1 116 | 14285826206   b4 4 | 1121980384   b3S 729 | 992158870
--           b2 50 | 931799119      n4 196 | 915508281   n1 290 | 734344384
--           n2 210 | 261394666     b3C 27 | 254740242
-- Total do sistema: 19497752152
-- (A aba Totais_Fonte traz diferenças de poucas unidades de R$ mil em
--  relação a essas somas: arredondamento da própria fonte.)

-- Identidade contábil: Ativo = Passivo Exigível + PL
SELECT MAX(ABS(ativo_total - passivo_exigivel - patrimonio_liquido)) AS maior_diferenca
FROM financeiros;
-- Esperado: 1 (diferença de arredondamento, em R$ mil)

-- Instituições com Patrimônio Líquido negativo (ROE não calculável)
SELECT COUNT(*) AS qtd_pl_negativo
FROM financeiros
WHERE patrimonio_liquido <= 0;
-- Esperado: 6


-- ====================================================================
-- PARTE 4 | EXEMPLOS DO MÓDULO
-- Execute um a um e observe os resultados
-- ====================================================================

-- ------------------------------------------------------------
-- Exemplo 1 | SELECT / FROM / WHERE: listar instituições públicas
-- ------------------------------------------------------------

SELECT
    nome,
    tcb,
    uf
FROM instituicoes
WHERE tc = 1  -- 1 = Público
ORDER BY nome;


-- ------------------------------------------------------------
-- Exemplo 2 | WHERE com AND: bancos b1 com sede em SP
-- ------------------------------------------------------------

SELECT
    nome,
    ti,
    cidade
FROM instituicoes
WHERE tcb = 'b1'
  AND uf = 'SP'
ORDER BY nome;


-- ------------------------------------------------------------
-- Exemplo 3 | WHERE com IN: vários valores
-- ------------------------------------------------------------

SELECT
    nome,
    tcb,
    tc
FROM instituicoes
WHERE tcb IN ('n1', 'n4')
  AND tc != 1;  -- exclui públicas


-- ------------------------------------------------------------
-- Exemplo 4 | GROUP BY + COUNT: contar por TCB
-- ------------------------------------------------------------

SELECT
    tcb,
    COUNT(*) AS total_instituicoes
FROM instituicoes
GROUP BY tcb
ORDER BY total_instituicoes DESC;


-- ------------------------------------------------------------
-- Exemplo 5 | GROUP BY + JOIN: somar ativo por tipo de controle
-- ------------------------------------------------------------

SELECT
    c.descricao               AS tipo_controle,
    COUNT(*)                  AS qtd,
    SUM(f.ativo_total)        AS ativo_soma,
    ROUND(AVG(f.ativo_total)) AS ativo_medio,
    MAX(f.ativo_total)        AS maior_ativo
FROM instituicoes i
JOIN financeiros f    ON f.inst_id = i.id
JOIN tipos_controle c ON c.tc = i.tc
WHERE f.data_ref = '2026-06-01'
GROUP BY c.descricao
ORDER BY ativo_soma DESC;


-- ------------------------------------------------------------
-- Exemplo 6 | HAVING: UFs com mais de 50 instituições
-- ------------------------------------------------------------

SELECT
    uf,
    COUNT(*) AS total
FROM instituicoes
GROUP BY uf
HAVING COUNT(*) > 50
ORDER BY total DESC;


-- ------------------------------------------------------------
-- Exemplo 7 | ORDER BY + LIMIT: top 10 por ativo
-- ------------------------------------------------------------

SELECT
    i.nome,
    i.tcb,
    i.tc,
    f.ativo_total
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
WHERE f.data_ref = '2026-06-01'
  AND f.ativo_total IS NOT NULL   -- NULL viria primeiro em DESC no PostgreSQL
ORDER BY f.ativo_total DESC
LIMIT 10;


-- ------------------------------------------------------------
-- Exemplo 8 | INNER JOIN: mais de 100 agências
-- ------------------------------------------------------------

SELECT
    i.nome,
    i.uf,
    i.tcb,
    e.num_agencias,
    e.num_postos
FROM instituicoes i
INNER JOIN estrutura e ON e.inst_id = i.id
WHERE e.data_ref = '2026-06-01'
  AND e.num_agencias > 100
ORDER BY e.num_agencias DESC;


-- ------------------------------------------------------------
-- Exemplo 9 | LEFT JOIN + IS NULL: instituições sem dado financeiro (NI)
-- ------------------------------------------------------------

SELECT
    i.nome,
    i.tcb,
    i.uf,
    f.ativo_total
FROM instituicoes i
LEFT JOIN financeiros f
    ON f.inst_id = i.id
    AND f.data_ref = '2026-06-01'
WHERE f.ativo_total IS NULL;
-- Resultado esperado: 51 registros (as instituições NI da planilha)


-- ------------------------------------------------------------
-- Exemplo 10 | JOIN múltiplo: tabelas de dados + tabelas de códigos
-- ------------------------------------------------------------

SELECT
    i.nome,
    tcb.descricao  AS consolidado,
    tc.descricao   AS controle,
    ti.descricao   AS tipo_instituicao,
    f.ativo_total,
    f.carteira_credito,
    f.lucro_liquido,
    e.num_agencias
FROM instituicoes i
INNER JOIN financeiros f        ON f.inst_id = i.id
INNER JOIN estrutura e          ON e.inst_id = i.id
INNER JOIN tipos_consolidado tcb ON tcb.tcb = i.tcb
INNER JOIN tipos_controle tc    ON tc.tc = i.tc
INNER JOIN tipos_instituicao ti ON ti.ti = i.ti
WHERE f.data_ref = '2026-06-01'
  AND e.data_ref = '2026-06-01'
  AND i.tcb IN ('b1', 'b4')
ORDER BY f.ativo_total DESC;


-- ------------------------------------------------------------
-- Exemplo 11 | Subconsulta: acima da média
-- ------------------------------------------------------------

SELECT
    i.nome,
    f.ativo_total
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
WHERE f.data_ref = '2026-06-01'
  AND f.ativo_total > (
      SELECT AVG(ativo_total)
      FROM financeiros
      WHERE data_ref = '2026-06-01'
  )
ORDER BY f.ativo_total DESC;


-- ------------------------------------------------------------
-- Exemplo 12 | CTE (WITH): calcular e classificar ROE
-- (mesmos cortes do exercício 14 da aba Exerc_Básico)
-- ------------------------------------------------------------

WITH base AS (
    SELECT
        i.nome,
        i.tcb,
        i.tc,
        ROUND(
            CAST(f.lucro_liquido AS NUMERIC)
            / NULLIF(f.patrimonio_liquido, 0) * 100, 2
        ) AS roe_pct
    FROM instituicoes i
    JOIN financeiros f ON f.inst_id = i.id
    WHERE f.data_ref = '2026-06-01'
      AND f.patrimonio_liquido > 0
)
SELECT
    nome, tcb, tc, roe_pct,
    CASE
        WHEN roe_pct > 7.5 THEN 'Excelente'
        WHEN roe_pct > 4   THEN 'Bom'
        WHEN roe_pct > 0   THEN 'Fraco'
        ELSE 'Prejuízo'
    END AS classificacao_roe
FROM base
ORDER BY roe_pct DESC;
-- Atenção: o arredondamento para 2 casas pode mudar a classe de quem
-- está exatamente na fronteira. Para classificar, compare o valor sem arredondar.


