WHERE f.data_ref = '2026-06-01'
  AND i.uf = 'SP'
  AND f.lucro_liquido > 0;
-- Esperado: 495


-- ------------------------------------------------------------
-- Gabarito | Exercício B12
-- ------------------------------------------------------------

SELECT SUM(f.lucro_liquido) AS lucro_estrangeiras
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
WHERE f.data_ref = '2026-06-01'
  AND i.tc = 3;
-- Esperado: 27091361


-- ------------------------------------------------------------
-- Gabarito | Exercício B13
-- ------------------------------------------------------------

WITH porte AS (
    SELECT
        f.ativo_total,
        CASE
            WHEN f.ativo_total IS NULL     THEN 'Sem dado'
            WHEN f.ativo_total > 100000000 THEN 'Grande'
            ELSE 'Média/Pequena'
        END AS porte
    FROM financeiros f
    WHERE f.data_ref = '2026-06-01'
)
SELECT
    porte,
    COUNT(*)          AS qtd,
    SUM(ativo_total)  AS ativo_soma,
    ROUND(100.0 * SUM(ativo_total) / SUM(SUM(ativo_total)) OVER (), 1) AS pct_ativo
FROM porte
GROUP BY porte
ORDER BY qtd;
-- Esperado: Grande 24 (77,7% do ativo) | Sem dado 51 | Média/Pequena 1547 (22,3%)


-- ------------------------------------------------------------
-- Gabarito | Exercício B14
-- ------------------------------------------------------------

WITH roe AS (
    SELECT
        CASE WHEN f.patrimonio_liquido > 0
             THEN f.lucro_liquido::NUMERIC / f.patrimonio_liquido
        END AS roe
    FROM financeiros f
    WHERE f.data_ref = '2026-06-01'
)
SELECT
    CASE
        WHEN roe IS NULL  THEN 'Sem dado'
        WHEN roe > 0.075  THEN 'Excelente'
        WHEN roe > 0.04   THEN 'Bom'
        WHEN roe > 0      THEN 'Fraco'
        ELSE 'Prejuízo'
    END       AS classe_roe,
    COUNT(*)  AS qtd
FROM roe
GROUP BY 1
ORDER BY qtd DESC;
-- Esperado: Excelente 458 | Fraco 384 | Prejuízo 367 | Bom 356 | Sem dado 57


-- ------------------------------------------------------------
-- Gabarito | Exercício B15
-- ------------------------------------------------------------

SELECT i.nome, f.ativo_total, f.patrimonio_liquido, f.lucro_liquido
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
WHERE i.nome LIKE 'NU FINANCEIRA%';
-- Esperado: ativo_total = 267624695 | lucro_liquido = 4194823
-- No SQL não há o problema da "correspondência aproximada" do PROCV:
-- o LIKE devolve todas as linhas que casam com o padrão.


-- ------------------------------------------------------------
-- Gabarito | Exercício I1
-- ------------------------------------------------------------

SELECT
    i.tcb,
    COUNT(*)                         AS qtd,
    SUM(f.ativo_total)               AS ativo_soma,
    ROUND(AVG(f.carteira_credito), 2) AS credito_medio,
    SUM(f.lucro_liquido)             AS lucro_soma,
    ROUND(100.0 * COUNT(*)             / SUM(COUNT(*))             OVER (), 1) AS pct_instituicoes,
    ROUND(100.0 * SUM(f.ativo_total)   / SUM(SUM(f.ativo_total))   OVER (), 1) AS pct_ativo,
    ROUND(100.0 * SUM(f.lucro_liquido) / SUM(SUM(f.lucro_liquido)) OVER (), 1) AS pct_lucro
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
WHERE f.data_ref = '2026-06-01'
GROUP BY i.tcb
ORDER BY ativo_soma DESC;
-- Esperado (igual à aba Tabela_TCB): b1 = 116 inst. | 73,3% do ativo | 52,5% do lucro;
-- b3S = 729 inst. (44,9% das instituições) com apenas 5,1% do ativo.


-- ------------------------------------------------------------
-- Gabarito | Exercício I2
-- ------------------------------------------------------------

SELECT
    c.descricao AS tipo_controle,
    ROUND(100 * AVG(
        CASE WHEN f.patrimonio_liquido > 0
             THEN f.lucro_liquido::NUMERIC / f.patrimonio_liquido END
    ), 1) AS roe_medio_simples_pct,
    ROUND(100.0 * SUM(f.lucro_liquido) / SUM(f.patrimonio_liquido), 1) AS roe_agregado_pct
FROM instituicoes i
JOIN financeiros f    ON f.inst_id = i.id
JOIN tipos_controle c ON c.tc = i.tc
WHERE f.data_ref = '2026-06-01'
GROUP BY c.tc, c.descricao
ORDER BY c.tc;
-- Esperado:  Público           8,0 | 5,3
--            Privado Nacional  1,4 | 8,5
--            Estrangeiro      -3,4 | 7,7
-- A média simples dá o mesmo peso a uma cooperativa minúscula e a um
-- grande banco; o ROE agregado pondera pelo capital. Por isso os
-- rankings se invertem.


-- ------------------------------------------------------------
-- Gabarito | Exercício I3
-- ------------------------------------------------------------

SELECT
    c.descricao AS tipo_controle,
    COUNT(*)            AS qtd,
    ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 1)                 AS pct_instituicoes,
    SUM(f.ativo_total)  AS ativo_soma,
    ROUND(100.0 * SUM(f.ativo_total) / SUM(SUM(f.ativo_total)) OVER (), 1) AS pct_ativo
FROM instituicoes i
JOIN financeiros f    ON f.inst_id = i.id
JOIN tipos_controle c ON c.tc = i.tc
WHERE f.data_ref = '2026-06-01'
GROUP BY c.tc, c.descricao
ORDER BY c.tc;
-- Esperado: Público 39 (2,4%) | 32,8% do ativo
--           Privado Nacional 1353 (83,4%) | 50,1% do ativo
--           Estrangeiro 230 (14,2%) | 17,2% do ativo


-- ------------------------------------------------------------
-- Gabarito | Exercício I4
-- ------------------------------------------------------------

-- a) Toda a base
SELECT nome, tcb, ativo_total,
       ROUND(100.0 * lucro_liquido / patrimonio_liquido, 1) AS roe_pct
FROM vw_base_fdata
WHERE patrimonio_liquido > 0
ORDER BY lucro_liquido::NUMERIC / patrimonio_liquido DESC
LIMIT 5;
-- Esperado: GREENPASS (168,5%), BOC BRASIL (147,1%), CAIXA DTVM (90,7%),
--           BB GESTÃO DE RECURSOS DTVM (87,1%), EFEX IP (82,1%)

-- b) Só Ativo Total acima de R$ 1 bilhão
SELECT nome, tcb, ativo_total,
       ROUND(100.0 * lucro_liquido / patrimonio_liquido, 1) AS roe_pct
FROM vw_base_fdata
WHERE patrimonio_liquido > 0
  AND ativo_total > 1000000
ORDER BY lucro_liquido::NUMERIC / patrimonio_liquido DESC
LIMIT 5;
-- Esperado: BB GESTÃO DE RECURSOS DTVM (87,1%), CITIBANK DTVM (63,3%),
--           DAYCOVAL LEASING (56,0%), BTG PACTUAL SERVIÇOS FINANCEIROS DTVM (46,9%),
--           CLOUDWALK FINANCEIRA (44,5%)


-- ------------------------------------------------------------
-- Gabarito | Exercício I5
-- ------------------------------------------------------------

WITH alav AS (
    SELECT
        i.nome,
        i.tcb,
        f.passivo_exigivel::NUMERIC / f.patrimonio_liquido AS alavancagem
    FROM instituicoes i
    JOIN financeiros f ON f.inst_id = i.id
    WHERE f.data_ref = '2026-06-01'
      AND f.patrimonio_liquido > 0
)
SELECT
    COUNT(*)                                                           AS qtd_calculadas,
    ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY alavancagem)::NUMERIC, 2) AS mediana,
    ROUND(MAX(alavancagem), 1)                                         AS maior,
    (SELECT nome FROM alav ORDER BY alavancagem DESC LIMIT 1)          AS mais_alavancada
FROM alav;
-- Esperado: 1565 | 3.55 | 505.2 | BANCO DIGIO S.A. (TCB b2)
-- (excluídas: 51 NI e 6 com PL <= 0)


-- ------------------------------------------------------------
-- Gabarito | Exercício I6
-- ------------------------------------------------------------

SELECT
    i.tcb,
    COUNT(*) AS qtd
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
WHERE f.data_ref = '2026-06-01'
  AND f.patrimonio_liquido > 0
  AND f.carteira_credito >= 10 * f.patrimonio_liquido
GROUP BY ROLLUP (i.tcb)
ORDER BY qtd DESC;
-- Esperado: total 21 | b1 11 | n1 5 | n4 3 | b2 2
-- (a linha com tcb NULL é o total geral gerado pelo ROLLUP)


-- ------------------------------------------------------------
-- Gabarito | Exercício I7
-- ------------------------------------------------------------

SELECT
    COUNT(*) FILTER (WHERE i.uf = 'SP')  AS sp_acima_1bi,
    COUNT(*)                             AS brasil_acima_1bi,
    ROUND(100.0 * COUNT(*) FILTER (WHERE i.uf = 'SP') / COUNT(*), 1) AS pct_sp
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
WHERE f.data_ref = '2026-06-01'
  AND f.ativo_total > 1000000;
-- Esperado: 207 | 511 | 40.5


-- ------------------------------------------------------------
-- Gabarito | Exercício I8
-- ------------------------------------------------------------

SELECT
    i.tcb,
    COUNT(*)            AS qtd_sem_agencia,
    SUM(f.ativo_total)  AS ativo_soma,
    ROUND(100.0 * SUM(f.ativo_total)
          / (SELECT SUM(ativo_total) FROM financeiros WHERE data_ref = '2026-06-01'), 1) AS pct_ativo_sistema
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
JOIN estrutura e   ON e.inst_id = i.id
WHERE f.data_ref = '2026-06-01'
  AND e.data_ref = '2026-06-01'
  AND e.num_agencias = 0
GROUP BY ROLLUP (i.tcb)
ORDER BY qtd_sem_agencia DESC;
-- Esperado: total 756 | 1246899112 | 6,4% do ativo; b3S 729 e b3C 27.
-- Não: as cooperativas registram zero agências por regra da fonte,
-- e bancos digitais (n1, n4) aparecem com agência cadastrada.
-- "Sem agência" não serve como proxy de "digital" nesta base.


-- ------------------------------------------------------------
-- Gabarito | Exercício I9
-- ------------------------------------------------------------

SELECT
    uf,
    COUNT(*) AS qtd,
    ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 1) AS pct
FROM instituicoes
GROUP BY uf
ORDER BY qtd DESC;
-- Esperado: SP 684 (42,2%) | MG 210 (12,9%) | RS 145 (8,9%)
--           PR 121 (7,5%)  | SC 118 (7,3%)  | demais 344 (21,2%)


-- ====================================================================
-- PARTE 7 | ANÁLISE FINAL
-- Queries para o projeto final do módulo (aba Template_Análise)
-- ====================================================================

-- ------------------------------------------------------------
-- Visão geral do sistema financeiro (seção 2 do Template_Análise)
-- ------------------------------------------------------------

SELECT
    COUNT(*)                    AS total_instituicoes,
    COUNT(f.ativo_total)        AS com_dados,
    SUM(f.ativo_total)          AS ativo_total_sistema,
    SUM(f.carteira_credito)     AS credito_total,
    SUM(f.lucro_liquido)        AS lucro_total,
    ROUND(100.0 * SUM(f.lucro_liquido) / SUM(f.patrimonio_liquido), 2) AS roe_agregado_pct,
    ROUND(AVG(f.ativo_total))   AS ativo_medio,
    PERCENTILE_CONT(0.5)
        WITHIN GROUP (ORDER BY f.ativo_total)      AS ativo_mediano,
    PERCENTILE_CONT(0.5)
        WITHIN GROUP (ORDER BY f.carteira_credito) AS credito_mediano
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
WHERE f.data_ref = '2026-06-01';


-- ------------------------------------------------------------
-- Concentração: participação acumulada das maiores instituições
-- ------------------------------------------------------------

WITH ranking AS (
    SELECT
        i.nome,
        f.ativo_total,
        ROW_NUMBER() OVER (ORDER BY f.ativo_total DESC) AS posicao,
        SUM(f.ativo_total) OVER (ORDER BY f.ativo_total DESC)
            / SUM(f.ativo_total) OVER () * 100           AS pct_acumulado
    FROM instituicoes i
    JOIN financeiros f ON f.inst_id = i.id
    WHERE f.data_ref = '2026-06-01'
      AND f.ativo_total IS NOT NULL
)
SELECT posicao, nome, ativo_total, ROUND(pct_acumulado, 1) AS pct_acumulado
FROM ranking
WHERE posicao IN (1, 5, 10, 20, 50, 100)
ORDER BY posicao;


-- ------------------------------------------------------------
-- Concentração por tipo de controle
-- ------------------------------------------------------------

SELECT
    i.tc,
    c.descricao         AS tipo,
    COUNT(*)            AS qtd,
    SUM(f.ativo_total)  AS ativo_soma,
    ROUND(100.0 * SUM(f.ativo_total)
          / SUM(SUM(f.ativo_total)) OVER (), 1) AS pct_ativo
FROM instituicoes i
JOIN financeiros f    ON f.inst_id = i.id
JOIN tipos_controle c ON c.tc = i.tc
WHERE f.data_ref = '2026-06-01'
GROUP BY i.tc, c.descricao
ORDER BY ativo_soma DESC;


-- ------------------------------------------------------------
-- Perfil por tipo de instituição (TI)
-- ------------------------------------------------------------

SELECT
    ti.ti,
    ti.descricao,
    COUNT(i.id)                     AS qtd,
    SUM(f.ativo_total)              AS ativo_soma,
    ROUND(100 * AVG(f.carteira_credito::NUMERIC / NULLIF(f.ativo_total, 0)), 1) AS credito_ativo_medio_pct,
    SUM(f.lucro_liquido)            AS lucro_soma
FROM tipos_instituicao ti
LEFT JOIN instituicoes i  ON i.ti = ti.ti
LEFT JOIN financeiros f   ON f.inst_id = i.id
GROUP BY ti.ti, ti.descricao
ORDER BY ativo_soma DESC NULLS LAST;
-- Os códigos 3, 7 e 31 aparecem com qtd = 0: o LEFT JOIN preserva
-- as categorias sem instituições na base.


-- ------------------------------------------------------------
-- Estrutura física: agências e postos por TCB
-- ------------------------------------------------------------

SELECT
    i.tcb,
    CASE
        WHEN e.num_agencias = 0    THEN 'Sem agência'
        WHEN e.num_agencias <= 10  THEN 'Até 10 agências'
        ELSE 'Mais de 10 agências'
    END                     AS faixa_agencias,
    COUNT(*)                AS qtd,
    SUM(f.ativo_total)      AS ativo_soma,
    SUM(e.num_postos)       AS postos
FROM instituicoes i
JOIN financeiros f ON f.inst_id = i.id
JOIN estrutura e   ON e.inst_id = i.id
WHERE f.data_ref = '2026-06-01'
  AND e.data_ref = '2026-06-01'
GROUP BY i.tcb, faixa_agencias
ORDER BY i.tcb, faixa_agencias;


-- ------------------------------------------------------------
-- Ranking completo de rentabilidade (ROE), geral e dentro do TCB
-- ------------------------------------------------------------

WITH roe AS (
    SELECT
        v.nome,
        v.tcb,
        v.tc,
        v.ativo_total,
        v.num_agencias,
        v.lucro_liquido::NUMERIC / v.patrimonio_liquido AS roe
    FROM vw_base_fdata v
    WHERE v.patrimonio_liquido > 0
)
SELECT
    r.nome,
    r.tcb,
    c.descricao                                       AS tipo_controle,
    r.ativo_total,
    ROUND(r.roe * 100, 2)                             AS roe_pct,
    r.num_agencias,
    RANK() OVER (ORDER BY r.roe DESC)                 AS posicao_geral,
    RANK() OVER (PARTITION BY r.tcb ORDER BY r.roe DESC) AS posicao_no_tcb
FROM roe r
JOIN tipos_controle c ON c.tc = r.tc
ORDER BY posicao_geral;


